const CONCURSOS = [{"id":"PCAL","nome":"Polícia Civil de Alagoas","prioridade":1},{"id":"PF","nome":"Polícia Federal","prioridade":2},{"id":"PRF","nome":"Polícia Rodoviária Federal","prioridade":3},{"id":"PCDF","nome":"Polícia Civil do Distrito Federal","prioridade":4},{"id":"PCE","nome":"Polícias Civis Estaduais (demais)","prioridade":5},{"id":"SESAU","nome":"SESAU/AL — Especialista em Saúde","prioridade":6}];
